# Increase T_f * L scale to include high-mass bosons and top quark
T_f_full_zoo = 5e6  # tension-length product scaled up

# Recalculate theta_4 values under the new scaling
theta_4_full_zoo = {
    name: np.degrees(np.arcsin(np.sqrt(m / (k_m * T_f_full_zoo * L_scaled))))
    if m > 0 and m / (k_m * T_f_full_zoo * L_scaled) <= 1 else (0.0 if m == 0 else np.nan)
    for name, m in masses_theta.items()
}

# Build updated full zoo data structure
full_zoo_data = {
    name: {
        'Class': particle_classes[name],
        'Mass (MeV/c^2)': masses_theta[name],
        'theta_4 (deg)': theta_4_full_zoo[name]
    }
    for name in masses_theta
}

full_zoo_df = pd.DataFrame.from_dict(full_zoo_data, orient='index')
full_zoo_df.index.name = "Particle"

tools.display_dataframe_to_user(name="Full SAT Mark VI Particle Zoo Table", dataframe=full_zoo_df)

